+          <ThemedText style={tw`text-2xl font-bold mb-5 text-[#ff1493]`}>{bookName}</ThemedText>
+          <ThemedText style={tw`text-lg mb-5 ${isDarkMode ? 'text-white' : 'text-[#070c70]'}`}>{chapterTitle}</ThemedText>
