+import React, { useEffect, useState } from 'react';
+import { TouchableOpacity, ActivityIndicator, Alert } from 'react-native';
+import { Audio } from 'expo-av';
+import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
+import { useThemeColor } from '@/hooks/useThemeColor';
+import { ThemedText } from '@/components/ThemedText';
+import { ThemedView } from '@/components/ThemedView';
+
+const AudioPlayer = ({ audioUri, chapterTitle, onClose }) => {
+  const [sound, setSound] = useState(null);
+  const [isPlaying, setIsPlaying] = useState(false);
+  const [loading, setLoading] = useState(true);
+
+  const backgroundColor = useThemeColor({}, 'background');
+  const primaryColor = useThemeColor({}, 'primary');
+
+  useEffect(() => {
+    let isMounted = true;
+
+    const loadSound = async () => {
+      try {
+        if (!audioUri) {
+          throw new Error('No audio URI provided.');
+        }
+
+        const { sound: newSound } = await Audio.Sound.createAsync(
+          { uri: audioUri },
+          { shouldPlay: false }
+        );
+
+        if (isMounted) {
+          setSound(newSound);
+          setLoading(false);
+        }
+
+        newSound.setOnPlaybackStatusUpdate((status) => {
+          if (status.didJustFinish && isMounted) {
+            setIsPlaying(false);
+          }
+        });
+      } catch (error) {
+        console.error('Error loading audio:', error);
+        Alert.alert('Audio Error', error.message);
+        if (isMounted) {
+          setLoading(false);
+        }
+      }
+    };
+
+    loadSound();
+
+    return () => {
+      isMounted = false;
+      if (sound) {
+        sound.unloadAsync();
+      }
+    };
+  }, [audioUri]);
+
+  const togglePlayPause = async () => {
+    if (!sound) {
+      Alert.alert('Audio Error', 'Audio is not loaded.');
+      return;
+    }
+
+    try {
+      if (isPlaying) {
+        await sound.pauseAsync();
+      } else {
+        await sound.playAsync();
+      }
+      setIsPlaying(!isPlaying);
+    } catch (error) {
+      console.error('Playback error:', error);
+      Alert.alert('Playback Error', error.message);
+    }
+  };
+
+  return (
+    <ThemedView
+      style={{
+        position: 'absolute',
+        bottom: 0,
+        left: 0,
+        right: 0,
+        padding: 16,
+        borderTopWidth: 1,
+        flexDirection: 'row',
+        alignItems: 'center',
+        backgroundColor,
+      }}
+    >
+      {loading ? (
+        <ActivityIndicator size="small" color={primaryColor} />
+      ) : (
+        <>
+          <TouchableOpacity onPress={togglePlayPause} style={{ padding: 8 }}>
+            <MaterialCommunityIcons
+              name={isPlaying ? 'pause-circle-outline' : 'play-circle-outline'}
+              size={40}
+              color={primaryColor}
+            />
+          </TouchableOpacity>
+          <ThemedView style={{ flex: 1, marginLeft: 12 }}>
+            <ThemedText style={{ fontSize: 16, fontWeight: '600' }}>
+              {chapterTitle || 'Unknown Chapter'}
+            </ThemedText>
+          </ThemedView>
+          <TouchableOpacity onPress={onClose} style={{ padding: 8 }}>
+            <MaterialCommunityIcons
+              name="close-circle-outline"
+              size={30}
+              color={primaryColor}
+            />
+          </TouchableOpacity>
+        </>
+      )}
+    </ThemedView>
+  );
+};
+
+export default AudioPlayer;

