+import React, { useEffect, useState } from 'react';
+import { View, TouchableOpacity, ActivityIndicator, Alert, Text } from 'react-native';
+import { Audio } from 'expo-av';
+import Slider from '@react-native-community/slider';
+import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
+import { useThemeColor } from '@/hooks/useThemeColor';
+import { ThemedText } from '@/components/ThemedText';
+import { ThemedView } from '@/components/ThemedView';
+
+const AudioPlayer = ({ audioUri, chapterTitle, onClose, onNext, onPrev }) => {
+  const [sound, setSound] = useState(null);
+  const [isPlaying, setIsPlaying] = useState(false);
+  const [loading, setLoading] = useState(true);
+  const [position, setPosition] = useState(0);
+  const [duration, setDuration] = useState(1);
+  const [playbackSpeed, setPlaybackSpeed] = useState(1.0);
+  const [isLooping, setIsLooping] = useState(false);
+
+  const backgroundColor = useThemeColor({}, 'background');
+  const primaryColor = useThemeColor({}, 'primary');
+
+  useEffect(() => {
+    let isMounted = true;
+
+    const loadSound = async () => {
+      try {
+        if (!audioUri) throw new Error('No audio URI provided.');
+
+        const { sound: newSound } = await Audio.Sound.createAsync(
+          { uri: audioUri },
+          { shouldPlay: false, isLooping }
+        );
+
+        if (isMounted) {
+          setSound(newSound);
+          setLoading(false);
+        }
+
+        newSound.setOnPlaybackStatusUpdate((status) => {
+          if (status.didJustFinish && isMounted) {
+            setIsPlaying(false);
+          }
+          if (status.positionMillis && status.durationMillis) {
+            setPosition(status.positionMillis);
+            setDuration(status.durationMillis);
+          }
+        });
+      } catch (error) {
+        Alert.alert('Audio Error', error.message);
+        setLoading(false);
+      }
+    };
+
+    loadSound();
+
+    return () => {
+      isMounted = false;
+      if (sound) sound.unloadAsync();
+    };
+  }, [audioUri]);
+
+  const togglePlayPause = async () => {
+    if (!sound) return Alert.alert('Audio Error', 'Audio is not loaded.');
+    if (isPlaying) await sound.pauseAsync();
+    else await sound.playAsync();
+    setIsPlaying(!isPlaying);
+  };
+
+  const seekAudio = async (value) => {
+    if (sound) await sound.setPositionAsync(value);
+  };
+
+  const skipForward = async () => {
+    if (sound) {
+      const newPosition = position + 15000;
+      await sound.setPositionAsync(newPosition > duration ? duration : newPosition);
+    }
+  };
+
+  const skipBackward = async () => {
+    if (sound) {
+      const newPosition = position - 15000;
+      await sound.setPositionAsync(newPosition < 0 ? 0 : newPosition);
+    }
+  };
+
+  const toggleLoop = async () => {
+    if (sound) {
+      await sound.setIsLoopingAsync(!isLooping);
+      setIsLooping(!isLooping);
+    }
+  };
+
+  const changeSpeed = async () => {
+    const speeds = [0.75, 1.0, 1.25, 1.5];
+    const nextSpeed = speeds[(speeds.indexOf(playbackSpeed) + 1) % speeds.length];
+    if (sound) await sound.setRateAsync(nextSpeed, true);
+    setPlaybackSpeed(nextSpeed);
+  };
+
+  const formatTime = (millis) => {
+    const totalSeconds = Math.floor(millis / 1000);
+    const minutes = Math.floor(totalSeconds / 60);
+    const seconds = totalSeconds % 60;
+    return `${minutes}:${seconds < 10 ? '0' : ''}${seconds}`;
+  };
+
+  return (
+    <ThemedView
+      style={{
+        position: 'absolute',
+        bottom: 0,
+        left: 0,
+        right: 0,
+        padding: 16,
+        borderTopWidth: 1,
+        alignItems: 'center',
+        backgroundColor,
+      }}
+    >
+      {loading ? (
+        <ActivityIndicator size="small" color={primaryColor} />
+      ) : (
+        <>
+          <ThemedText style={{ fontSize: 16, fontWeight: '600', marginBottom: 8 }}>
+            {chapterTitle || 'Unknown Chapter'}
+          </ThemedText>
+
+          {/* Slider */}
+          <View style={{ flexDirection: 'row', alignItems: 'center', width: '100%' }}>
+            <Text style={{ color: primaryColor }}>{formatTime(position)}</Text>
+            <Slider
+              style={{ flex: 1, marginHorizontal: 10 }}
+              minimumValue={0}
+              maximumValue={duration}
+              value={position}
+              minimumTrackTintColor={primaryColor}
+              maximumTrackTintColor="gray"
+              thumbTintColor={primaryColor}
+              onSlidingComplete={seekAudio}
+            />
+            <Text style={{ color: primaryColor }}>{formatTime(duration)}</Text>
+          </View>
+
+          {/* Controls */}
+          <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 12 }}>
+            <TouchableOpacity onPress={onPrev} style={{ padding: 8 }}>
+              <MaterialCommunityIcons name="skip-previous" size={35} color={primaryColor} />
+            </TouchableOpacity>
+
+            <TouchableOpacity onPress={skipBackward} style={{ padding: 8 }}>
+              <MaterialCommunityIcons name="rewind-15" size={35} color={primaryColor} />
+            </TouchableOpacity>
+
+            <TouchableOpacity onPress={togglePlayPause} style={{ padding: 8 }}>
+              <MaterialCommunityIcons
+                name={isPlaying ? 'pause-circle-outline' : 'play-circle-outline'}
+                size={45}
+                color={primaryColor}
+              />
+            </TouchableOpacity>
+
+            <TouchableOpacity onPress={skipForward} style={{ padding: 8 }}>
+              <MaterialCommunityIcons name="fast-forward-15" size={35} color={primaryColor} />
+            </TouchableOpacity>
+
+            <TouchableOpacity onPress={onNext} style={{ padding: 8 }}>
+              <MaterialCommunityIcons name="skip-next" size={35} color={primaryColor} />
+            </TouchableOpacity>
+          </View>
+
+          {/* Extra Controls */}
+          <View style={{ flexDirection: 'row', marginTop: 10, alignItems: 'center' }}>
+            <TouchableOpacity onPress={changeSpeed} style={{ padding: 8 }}>
+              <MaterialCommunityIcons name="speedometer" size={30} color={primaryColor} />
+              <Text style={{ color: primaryColor, fontSize: 12, textAlign: 'center' }}>
+                {playbackSpeed}x
+              </Text>
+            </TouchableOpacity>
+
+            <TouchableOpacity onPress={toggleLoop} style={{ padding: 8 }}>
+              <MaterialCommunityIcons
+                name={isLooping ? 'repeat' : 'repeat-off'}
+                size={30}
+                color={primaryColor}
+              />
+            </TouchableOpacity>
+          </View>
+
+          {/* Close Button */}
+          <TouchableOpacity onPress={onClose} style={{ padding: 8, marginTop: 10 }}>
+            <MaterialCommunityIcons name="close-circle-outline" size={30} color={primaryColor} />
+          </TouchableOpacity>
+        </>
+      )}
+    </ThemedView>
+  );
+};
+
+export default AudioPlayer;
+

